   123	class OrderLifecycleTest {
   124	    private static final Instant NOW = Instant.parse("2026-10-14T15:30:00Z");
   125	
   126	    private static String courierOrder(String sku, int qty, String coupon, String tier) {
   127	        return CheckoutExamplesTest.body("[{\"sku\":\"" + sku + "\",\"quantity\":" + qty + "}]", "COURIER", coupon,
   128	                "PIX", 1, tier, "SOUTH");
   129	    }
   130	
   131	    private static String pay(String tx, String at) {
   132	        return "{\"transactionId\":\"" + tx + "\",\"paidAt\":\"" + at + "\"}";
   133	    }
   134	
   135	    @Test
   136	    void paymentIsIdempotentAndUpdatesStockCreditAndNotifications() {
   137	        try (TestApp app = new TestApp(NOW)) {
   138	            var created = app.post("/orders", courierOrder("FON-001", 2, null, "GOLD"));
   139	            assertEquals(201, created.status());
   140	            String id = created.body().get("id").asText();
   141	            assertEquals("AWAITING_PAYMENT", created.body().get("status").asText());
   142	            assertEquals("2026-10-14T15:30:00Z", created.body().get("createdAt").asText());
   143	            assertEquals(200, app.get("/customers/12345678909").status() == 200 ? 200 : 0);
   144	
   145	            var first = app.post("/orders/" + id + "/payment", pay("TX-1", "2026-10-16T15:30:00Z"));
   146	            assertEquals(200, first.status());
   147	            assertEquals("PAID", first.body().get("status").asText());
   148	            var again = app.post("/orders/" + id + "/payment", pay("TX-1", "2026-10-16T15:30:00Z"));
   149	            assertEquals(200, again.status());
   150	            assertEquals(3, app.get("/products/FON-001").body().get("stock").asInt());
   151	            assertEquals("19.99", app.get("/customers/12345678909").body().get("creditBalance").decimalValue().toPlainString());
   152	            assertEquals(1, app.get("/customers/12345678909/notifications").body().size());
   153	
   154	            var other = app.post("/orders/" + id + "/payment", pay("TX-2", "2026-10-16T15:30:00Z"));
   155	            assertEquals(409, other.status());
   156	            assertEquals("OPERATION_NOT_ALLOWED", other.body().get("error").asText());
   157	
   158	            assertEquals(409, app.post("/orders/" + id + "/delivery", null).status());
   159	            var shipped = app.post("/orders/" + id + "/shipment", "{\"trackingCode\":\"BR1\"}");
   160	            assertEquals("SHIPPED", shipped.body().get("status").asText());
   161	            assertEquals("BR1", shipped.body().get("trackingCode").asText());
   162	            assertEquals(409, app.post("/orders/" + id + "/cancellation", null).status());
   163	            assertEquals("DELIVERED", app.post("/orders/" + id + "/delivery", null).body().get("status").asText());
   164	        }
   165	    }
   166	
   167	    @Test
   168	    void cancellingPaidOrderRestoresStockAndCredit() {
   169	        try (TestApp app = new TestApp(NOW)) {
   170	            String id = app.post("/orders", courierOrder("FON-001", 2, null, "SILVER")).body().get("id").asText();
   171	            app.post("/orders/" + id + "/payment", pay("TX-1", "2026-10-14T15:30:00Z"));
   172	            assertEquals(200, app.post("/orders/" + id + "/cancellation", null).status());
   173	            assertEquals(5, app.get("/products/FON-001").body().get("stock").asInt());
   174	            assertEquals("0.00", app.get("/customers/12345678909").body().get("creditBalance").decimalValue().toPlainString());
   175	            var notes = app.get("/customers/12345678909/notifications").body();
   176	            assertEquals("ORDER_CANCELLED", notes.get(1).get("type").asText());
   177	            assertEquals("READ", app.post("/notifications/" + notes.get(0).get("id").asLong() + "/read", null)
   178	                    .body().get("status").asText());
   179	        }
   180	    }
