   182	    @Test
   183	    void expiredPaymentCancelsOrderAndReplayGivesSameRefusal() {
   184	        try (TestApp app = new TestApp(NOW)) {
   185	            String id = app.post("/orders", courierOrder("CAM-001", 1, null, "BRONZE")).body().get("id").asText();
   186	            var late = app.post("/orders/" + id + "/payment", pay("TX-1", "2026-10-16T15:30:01Z"));
   187	            assertEquals(409, late.status());
   188	            assertEquals("ORDER_EXPIRED", late.body().get("error").asText());
   189	            assertEquals("CANCELLED", app.get("/orders/" + id).body().get("status").asText());
   190	            var replay = app.post("/orders/" + id + "/payment", pay("TX-1", "2026-10-14T16:00:00Z"));
   191	            assertEquals("ORDER_EXPIRED", replay.body().get("error").asText());
   192	            assertEquals(50, app.get("/products/CAM-001").body().get("stock").asInt());
   193	        }
   194	    }
   195	
   196	    @Test
   197	    void lastPieceIsSoldOnlyOnce() {
   198	        try (TestApp app = new TestApp(NOW)) {
   199	            String a = app.post("/orders", courierOrder("MOC-001", 1, null, "BRONZE")).body().get("id").asText();
   200	            String b = app.post("/orders", courierOrder("MOC-001", 1, null, "BRONZE")).body().get("id").asText();
   201	            assertEquals(200, app.post("/orders/" + a + "/payment", pay("TX-A", "2026-10-14T16:00:00Z")).status());
   202	            var second = app.post("/orders/" + b + "/payment", pay("TX-B", "2026-10-14T16:00:00Z"));
   203	            assertEquals(409, second.status());
   204	            assertEquals("INSUFFICIENT_STOCK", second.body().get("error").asText());
   205	            assertEquals(0, app.get("/products/MOC-001").body().get("stock").asInt());
   206	            assertEquals("CANCELLED", app.get("/orders/" + b).body().get("status").asText());
   207	            assertTrue(app.get("/customers/12345678909/notifications").body().size() >= 2);
   208	        }
   209	    }
