   211	    @Test
   212	    void welcomeCouponOnlyForFirstPurchase() {
   213	        try (TestApp app = new TestApp(NOW)) {
   214	            String id = app.post("/orders", courierOrder("CAM-001", 1, "WELCOME10", "BRONZE")).body().get("id").asText();
   215	            assertEquals(201, app.post("/checkout/summary", courierOrder("CAM-001", 1, "WELCOME10", "BRONZE")).status() == 200 ? 201 : 0);
   216	            app.post("/orders/" + id + "/payment", pay("TX-1", "2026-10-14T16:00:00Z"));
   217	            var r = app.post("/checkout/summary", courierOrder("CAM-001", 1, "WELCOME10", "BRONZE"));
   218	            assertEquals("COUPON_NOT_APPLICABLE", r.body().get("error").asText());
   219	        }
   220	    }
   221	
   222	    @Test
   223	    void unknownResourcesAndValidation() {
   224	        try (TestApp app = new TestApp(NOW)) {
   225	            assertEquals("ORDER_NOT_FOUND", app.get("/orders/x").body().get("error").asText());
   226	            assertEquals("PRODUCT_NOT_FOUND", app.get("/products/x").body().get("error").asText());
   227	            assertEquals("CUSTOMER_NOT_FOUND", app.get("/customers/1/notifications").body().get("error").asText());
   228	            assertEquals("NOTIFICATION_NOT_FOUND", app.post("/notifications/9/read", null).body().get("error").asText());
   229	            assertEquals(404, app.post("/orders/x/payment", "{}").status());
   230	            String id = app.post("/orders", courierOrder("CAM-001", 1, null, "BRONZE")).body().get("id").asText();
   231	            assertEquals("INVALID_ORDER", app.post("/orders/" + id + "/payment", "{}").body().get("error").asText());
   232	            assertEquals("OPERATION_NOT_ALLOWED", app.post("/orders/" + id + "/shipment", "{\"trackingCode\":\"X\"}")
   233	                    .body().get("error").asText());
   234	        }
   235	    }
