   239	import com.fasterxml.jackson.databind.JsonNode;
   240	import io.javalin.Javalin;
   241	
   242	import java.net.URI;
   243	import java.net.http.HttpClient;
   244	import java.net.http.HttpRequest;
   245	import java.net.http.HttpResponse;
   246	import java.time.Clock;
   247	import java.time.Instant;
   248	import java.time.ZoneOffset;
   249	import java.util.Optional;
   250	
   251	/** Servidor real em porta livre, armazenamento em memória e transportadora de mentira. */
   252	class TestApp implements AutoCloseable {
   253	    record Reply(int status, JsonNode body) {}
   254	
   255	    private static final com.fasterxml.jackson.databind.ObjectMapper READER = new com.fasterxml.jackson.databind.ObjectMapper()
   256	            .enable(com.fasterxml.jackson.databind.DeserializationFeature.USE_BIG_DECIMAL_FOR_FLOATS)
   257	            .configure(com.fasterxml.jackson.databind.cfg.JsonNodeFeature.STRIP_TRAILING_BIGDECIMAL_ZEROES, false);
   258	
   259	    volatile Optional<CarrierQuote> carrierAnswer = Optional.empty();
   260	    volatile boolean carrierDown = false;
   261	    final MemoryStore store = new MemoryStore();
   262	    final Javalin app;
   263	    private final HttpClient http = HttpClient.newHttpClient();
   264	
   265	    TestApp(Instant now) {
   266	        CarrierGateway gateway = (zip, grams, service) -> {
   267	            if (carrierDown) throw new CarrierDownException("down", null);
   268	            return carrierAnswer;
   269	        };
   270	        app = Api.create(store, gateway, Clock.fixed(now, ZoneOffset.UTC)).start(0);
   271	    }
   272	
   273	    void carrier(int cents, int hours) {
   274	        carrierAnswer = Optional.of(new CarrierQuote(java.math.BigDecimal.valueOf(cents, 2), hours));
   275	    }
   276	
   277	    Reply post(String path, String body) {
   278	        return send(HttpRequest.newBuilder(uri(path)).header("Content-Type", "application/json")
   279	                .POST(HttpRequest.BodyPublishers.ofString(body == null ? "" : body)).build());
   280	    }
   281	
   282	    Reply get(String path) {
   283	        return send(HttpRequest.newBuilder(uri(path)).GET().build());
   284	    }
   285	
   286	    private URI uri(String path) {
   287	        return URI.create("http://localhost:" + app.port() + path);
   288	    }
   289	
   290	    private Reply send(HttpRequest request) {
   291	        try {
   292	            HttpResponse<String> r = http.send(request, HttpResponse.BodyHandlers.ofString());
   293	            return new Reply(r.statusCode(), READER.readTree(r.body()));
   294	        } catch (Exception e) {
   295	            throw new IllegalStateException(e);
   296	        }
   297	    }
   298	
   299	    @Override
   300	    public void close() {
   301	        app.stop();
   302	    }
   303	}
