   306	import com.sun.net.httpserver.HttpServer;
   307	import org.junit.jupiter.api.Test;
   308	
   309	import java.net.InetSocketAddress;
   310	import java.nio.charset.StandardCharsets;
   311	import java.util.Optional;
   312	
   313	import static org.junit.jupiter.api.Assertions.assertEquals;
   314	import static org.junit.jupiter.api.Assertions.assertThrows;
   315	
   316	class TransLogGatewayTest {
   317	    private static HttpServer server(int status, String body, long delayMs) throws Exception {
   318	        HttpServer s = HttpServer.create(new InetSocketAddress("localhost", 0), 0);
   319	        s.createContext("/v2/quote", ex -> {
   320	            try {
   321	                Thread.sleep(delayMs);
   322	            } catch (InterruptedException ignored) {
   323	            }
   324	            byte[] bytes = body.getBytes(StandardCharsets.UTF_8);
   325	            ex.sendResponseHeaders(status, bytes.length);
   326	            ex.getResponseBody().write(bytes);
   327	            ex.close();
   328	        });
   329	        s.start();
   330	        return s;
   331	    }
   332	
   333	    private static TransLogGateway gateway(HttpServer s) {
   334	        return new TransLogGateway("http://localhost:" + s.getAddress().getPort() + "/");
   335	    }
   336	
   337	    @Test
   338	    void parsesQuoteAndNotServed() throws Exception {
   339	        HttpServer ok = server(200, "{\"price_cents\":3310,\"eta_hours\":41}", 0);
   340	        HttpServer none = server(200, "{\"error\":\"ZIP_NOT_SERVED\"}", 0);
   341	        try {
   342	            CarrierQuote q = gateway(ok).quote("01310100", 1800, "EXP").orElseThrow();
   343	            assertEquals("33.10", q.price().toPlainString());
   344	            assertEquals(41, q.etaHours());
   345	            assertEquals(Optional.empty(), gateway(none).quote("01310100", 1800, "EXP"));
   346	        } finally {
   347	            ok.stop(0);
   348	            none.stop(0);
   349	        }
   350	    }
   351	
   352	    @Test
   353	    void anythingElseMeansDown() throws Exception {
   354	        HttpServer err = server(500, "{}", 0);
   355	        HttpServer odd = server(200, "{\"error\":\"OTHER\"}", 0);
   356	        HttpServer slow = server(200, "{\"price_cents\":1,\"eta_hours\":1}", 2600);
   357	        try {
   358	            assertThrows(CarrierDownException.class, () -> gateway(err).quote("01310100", 1, "STD"));
   359	            assertThrows(CarrierDownException.class, () -> gateway(odd).quote("01310100", 1, "STD"));
   360	            assertThrows(CarrierDownException.class, () -> gateway(slow).quote("01310100", 1, "STD"));
   361	            assertThrows(CarrierDownException.class, () -> new TransLogGateway(null).quote("01310100", 1, "STD"));
   362	        } finally {
   363	            err.stop(0);
   364	            odd.stop(0);
   365	            slow.stop(0);
   366	        }
   367	    }
   368	}
