  156	/** Armazenamento em memória, usado nos testes (sem banco). Uma transação por vez. */
  157	class MemoryStore implements Store {
  158	    private final ReentrantLock lock = new ReentrantLock();
  159	    private final Map<String, Product> products = new HashMap<>();
  160	    private final Map<String, Order> orders = new HashMap<>();
  161	    private final Map<String, Customer> customers = new HashMap<>();
  162	    private final Map<String, PaymentRecord> payments = new HashMap<>();
  163	    private final List<Notification> notifications = new ArrayList<>();
  164	
  165	    MemoryStore() {
  166	        for (Product p : Catalog.initial()) products.put(p.sku(), p);
  167	    }
  168	
  169	    @Override
  170	    public <T> T transaction(Function<Tx, T> work) {
  171	        lock.lock();
  172	        try {
  173	            return work.apply(new MemoryTx());
  174	        } finally {
  175	            lock.unlock();
  176	        }
  177	    }
