  179	    private final class MemoryTx implements Tx {
  180	        public Optional<Product> findProduct(String sku) {
  181	            return Optional.ofNullable(products.get(sku));
  182	        }
  183	
  184	        public List<Product> lockProducts(Collection<String> skus) {
  185	            List<Product> result = new ArrayList<>();
  186	            for (String sku : new TreeSet<>(skus)) {
  187	                Product p = products.get(sku);
  188	                if (p != null) result.add(p);
  189	            }
  190	            return result;
  191	        }
  192	
  193	        public void addStock(String sku, int delta) {
  194	            Product p = products.get(sku);
  195	            if (p.stock() + delta < 0) throw new IllegalStateException("negative stock");
  196	            products.put(sku, new Product(sku, p.name(), p.price(), p.weightKg(), p.stock() + delta, p.discontinued()));
  197	        }
  198	
  199	        public Optional<Order> findOrder(String id) {
  200	            return Optional.ofNullable(orders.get(id));
  201	        }
  202	
  203	        public Optional<Order> lockOrder(String id) {
  204	            return findOrder(id);
  205	        }
  206	
  207	        public void insertOrder(Order order) {
  208	            orders.put(order.id(), order);
  209	        }
  210	
  211	        public void updateOrder(Order order) {
  212	            orders.put(order.id(), order);
  213	        }
  214	
  215	        public boolean hasFulfilledOrder(String cpf) {
  216	            return orders.values().stream().anyMatch(o -> o.cpf().equals(cpf)
  217	                    && (o.status() == OrderStatus.PAID || o.status() == OrderStatus.SHIPPED
  218	                    || o.status() == OrderStatus.DELIVERED));
  219	        }
