  223	        }
  224	
  225	        public Optional<Customer> findCustomer(String cpf) {
  226	            return Optional.ofNullable(customers.get(cpf));
  227	        }
  228	
  229	        public void addCredit(String cpf, BigDecimal delta) {
  230	            Customer c = customers.get(cpf);
  231	            customers.put(cpf, new Customer(cpf, Money.round(c.creditBalance().add(delta))));
  232	        }
  233	
  234	        public Optional<PaymentRecord> findPayment(String orderId, String transactionId) {
  235	            return Optional.ofNullable(payments.get(orderId + "|" + transactionId));
  236	        }
  237	
  238	        public void savePayment(String orderId, String transactionId, PaymentRecord record) {
  239	            payments.put(orderId + "|" + transactionId, record);
  240	        }
  241	
  242	        public Notification addNotification(String cpf, NotificationType type, String orderId) {
  243	            Notification n = new Notification(notifications.size() + 1L, cpf, type, orderId, NotificationStatus.NEW);
  244	            notifications.add(n);
  245	            return n;
  246	        }
  247	
  248	        public List<Notification> notifications(String cpf) {
  249	            return notifications.stream().filter(n -> n.cpf().equals(cpf)).toList();
  250	        }
  251	
  252	        public Optional<Notification> markRead(long id) {
  253	            if (id < 1 || id > notifications.size()) return Optional.empty();
  254	            Notification n = notifications.get((int) id - 1);
  255	            Notification read = new Notification(n.id(), n.cpf(), n.type(), n.orderId(), NotificationStatus.READ);
  256	            notifications.set((int) id - 1, read);
  257	            return Optional.of(read);
  258	        }
  259	    }
